import os
import re
from typing import Any, Dict, List, Optional, Tuple

import requests


AZURE_CONTENT_SAFETY_ENDPOINT = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT", "").rstrip("/")
AZURE_CONTENT_SAFETY_KEY = os.getenv("AZURE_CONTENT_SAFETY_KEY", "")
AZURE_CONTENT_SAFETY_API_VERSION = os.getenv("AZURE_CONTENT_SAFETY_API_VERSION", "2023-10-01")
AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD = int(os.getenv("AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD", "2"))

_CATEGORY_MAP = {
    "Hate": "hate",
    "SelfHarm": "self_harm",
    "Sexual": "sexual",
    "Violence": "violence",
}


def _api_url() -> str:
    if not AZURE_CONTENT_SAFETY_ENDPOINT:
        raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT is required")
    return f"{AZURE_CONTENT_SAFETY_ENDPOINT}/contentsafety/text:analyze?api-version={AZURE_CONTENT_SAFETY_API_VERSION}"


def _headers() -> Dict[str, str]:
    if not AZURE_CONTENT_SAFETY_KEY:
        raise ValueError("AZURE_CONTENT_SAFETY_KEY is required")
    return {
        "Content-Type": "application/json",
        "Ocp-Apim-Subscription-Key": AZURE_CONTENT_SAFETY_KEY,
    }


def _token_spans(text: str) -> List[Tuple[int, int]]:
    return [(m.start(), m.end()) for m in re.finditer(r"\S+", text)]


def _char_to_token_spans(text: str, spans: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    tokens = _token_spans(text)
    token_spans: List[Tuple[int, int]] = []
    for start, end in spans:
        token_start = None
        token_end = None
        for i, (ts, te) in enumerate(tokens):
            if token_start is None and te > start:
                token_start = i
            if ts < end:
                token_end = i
            if ts >= end:
                break
        if token_start is not None and token_end is not None:
            token_spans.append((token_start, token_end))
    return token_spans


def _mask_span(text: str, start: int, end: int, mask_char: str = "█") -> str:
    return text[:start] + (mask_char * max(0, end - start)) + text[end:]


def analyze_text(text: str) -> Dict[str, Any]:
    payload = {
        "text": text,
        "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
        "blocking": False,
    }
    resp = requests.post(_api_url(), headers=_headers(), json=payload, timeout=30)
    resp.raise_for_status()
    return resp.json()


def flag_or_redact_unsafe_spans(
    text: str,
    redact: bool = False,
    mask_char: str = "█",
) -> Dict[str, Any]:
    """
    Returns a dict with:
      - safe: bool
      - flagged_spans: list of character spans [(start, end), ...]
      - flagged_tokens: token span list [(start_token, end_token), ...]
      - categories: list of category summaries
      - text: redacted text if redact=True, otherwise original text
    """
    result = analyze_text(text)
    analysis = result.get("categoriesAnalysis", [])
    flagged_spans: List[Tuple[int, int]] = []
    category_summaries: List[Dict[str, Any]] = []

    for item in analysis:
        category = item.get("category")
        severity = int(item.get("severity", 0))
        category_key = _CATEGORY_MAP.get(category, category.lower() if isinstance(category, str) else str(category))
        category_summaries.append(
            {
                "category": category_key,
                "severity": severity,
                "detected": severity >= AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD,
            }
        )
        if severity >= AZURE_CONTENT_SAFETY_SEVERITY_THRESHOLD:
            # Azure Content Safety text analyze returns severities but not explicit spans.
            # Mark the whole text as unsafe for redaction when threshold is met.
            flagged_spans.append((0, len(text)))
            break

    safe = len(flagged_spans) == 0
    output_text = text

    if redact and flagged_spans:
        for start, end in sorted(flagged_spans, reverse=True):
            output_text = _mask_span(output_text, start, end, mask_char=mask_char)

    return {
        "safe": safe,
        "flagged_spans": flagged_spans,
        "flagged_tokens": _char_to_token_spans(text, flagged_spans),
        "categories": category_summaries,
        "text": output_text,
        "provider": "azure_ai_content_safety",
    }
